Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_shrink_array_malloc_failure(void) {
    // Setup: create a valid stack with capacity >= 2
    DArrayStack *stack = create_stack(4);
    TEST_ASSERT_NOT_NULL(stack);
    // Push some elements to ensure top is valid for copying
    int push_result = push(stack, 10);
    TEST_ASSERT_EQUAL_INT(0, push_result); // top becomes 0

    // The target path requires: ptr != NULL, cap >= 2, newCap = cap/2, newCap <= 0? (no, 4/2=2), malloc fails.
    // We need to fail the malloc inside shrink_array.
    // create_stack makes 2 allocations (struct + array). So we need to fail the 3rd allocation.
    malloc_fail_after(2);

    // Test: call shrink_array with valid parameters, expecting malloc failure
    DArrayStack *result = shrink_array(stack, 4);
    TEST_ASSERT_NULL(result); // Should return NULL due to malloc failure

    // Cleanup: stack is still valid (shrink_array failed, didn't free the struct)
    // The old array pointer is still valid because free(ptr->arrPtr) didn't happen.
    free_stack(stack);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_shrink_array_malloc_failure);
    return UNITY_END();
}

